  'Đang theo đuổi': { en: 'Active', zh: '进行中', ja: '取り組み中', ko: '진행 중', es: 'En curso', fr: 'En cours', de: 'Aktiv', th: 'กำลังมุ่งไป', id: 'Sedang dikejar' },
